SELECT DISTINCTROW [Имена-итогов].NUMB1, First([Имена-итогов].NAME) AS NAME1, [Рабочий(станции)].OES, [Рабочий(станции)].YEAR, Sum([Рабочий(станции)].NUST) AS NUST, Sum([Рабочий(станции)].E) AS E, Sum([Рабочий(станции)].EOTP) AS EOTP, IIf([EOTP]>0,[EUST]/[EOTP]*1000,0) AS EURT, Sum([Рабочий(станции)].EUST) AS EUST, Sum([Рабочий(станции)].Q) AS Q, IIf([Q]>0,[TUST]/[Q]*1000,0) AS TURT, Sum([Рабочий(станции)].TUST) AS TUST, Sum([Рабочий(станции)].B) AS B, Sum([Рабочий(станции)].GAZ) AS GAZ, Sum([Рабочий(станции)].MAZUT) AS MAZUT, Sum([Рабочий(станции)].TORF) AS TORF, Sum([Рабочий(станции)].SLAN) AS SLAN, Sum([Рабочий(станции)].PROCH) AS PROCH, Sum([Рабочий(станции)].UGOL) AS UGOL, Sum([Рабочий(станции)].DON) AS DON, Sum([Рабочий(станции)].PODM) AS PODM, Sum([Рабочий(станции)].PECH) AS PECH, Sum([Рабочий(станции)].ARKT) AS ARKT, Sum([Рабочий(станции)].KUZN) AS KUZN, Sum([Рабочий(станции)].URAL) AS URAL, Sum([Рабочий(станции)].BASHK) AS BASHK, Sum([Рабочий(станции)].KAZAH) AS [Sum-KAZAH], Sum([Рабочий(станции)].KAN) AS KAN, Sum([Рабочий(станции)].IRKUT) AS IRKUT, Sum([Рабочий(станции)].HAK) AS HAK, Sum([Рабочий(станции)].TUV) AS TUV, Sum([Рабочий(станции)].BUR) AS BUR, Sum([Рабочий(станции)].CHIT) AS CHIT, Sum([Рабочий(станции)].AMUR) AS [Sum-AMUR], Sum([Рабочий(станции)].URG) AS URG, Sum([Рабочий(станции)].PRIM) AS PRIM, Sum([Рабочий(станции)].PRIM) AS [Sum-PRIM], Sum([Рабочий(станции)].MAG) AS MAG, Sum([Рабочий(станции)].SAH) AS SAH, Sum([Рабочий(станции)].QOTR) AS QOTR, Sum([Рабочий(станции)].EWTP) AS EWTP, Sum([Рабочий(станции)].NT) AS NT
FROM [Рабочий(станции)] LEFT JOIN [Имена-итогов] ON [Рабочий(станции)].VED = [Имена-итогов].VED
WHERE ((([Рабочий(станции)].VED)>0))
GROUP BY [Имена-итогов].NUMB1, [Рабочий(станции)].OES, [Рабочий(станции)].YEAR
HAVING ((([Имена-итогов].NUMB1)=1 Or ([Имена-итогов].NUMB1)=8) AND (([Рабочий(станции)].OES)=2));
